// Пины
const int RELAY1_PIN = 2;
const int RELAY2_PIN = 3;
const int BUTTON_PIN = 4;

// Временные интервалы (в миллисекундах)
const unsigned long DELAY_1S = 1000;
const unsigned long IMPULSE_DURATION = 200;   // длительность импульса реле 2
const unsigned long DELAY_5S = 5000;

// Состояния автомата
enum State {
  IDLE,        // ожидание нажатия
  WAIT_1S,     // пауза 1 секунда после нажатия
  PULSE_ON,    // реле 2 включено (импульс)
  WAIT_5S      // пауза 5 секунд после импульса
};

State currentState = IDLE;
unsigned long stateStartTime = 0;   // время начала текущего состояния
bool lastButtonState = HIGH;        // для детектирования нажатия

void setup() {
  pinMode(RELAY1_PIN, OUTPUT);
  pinMode(RELAY2_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);

  digitalWrite(RELAY1_PIN, HIGH);   // реле 1 всегда включено
  digitalWrite(RELAY2_PIN, LOW);    // реле 2 выключено по умолчанию
}

void loop() {
  unsigned long currentMillis = millis();

  // Чтение состояния кнопки (LOW = нажата)
  bool buttonState = digitalRead(BUTTON_PIN);

  // Обработка конечного автомата
  switch (currentState) {
    case IDLE:
      // Ждём нажатия (переход с HIGH на LOW)
      if (lastButtonState == HIGH && buttonState == LOW) {
        // Запоминаем время и переходим в WAIT_1S
        stateStartTime = currentMillis;
        currentState = WAIT_1S;
      }
      break;

    case WAIT_1S:
      // Проверяем, прошла ли 1 секунда с момента нажатия
      if (currentMillis - stateStartTime >= DELAY_1S) {
        // Включаем реле 2
        digitalWrite(RELAY2_PIN, HIGH);
        stateStartTime = currentMillis;
        currentState = PULSE_ON;
      }
      break;

    case PULSE_ON:
      // Держим реле 2 включённым на время IMPULSE_DURATION
      if (currentMillis - stateStartTime >= IMPULSE_DURATION) {
        // Выключаем реле 2
        digitalWrite(RELAY2_PIN, LOW);
        stateStartTime = currentMillis;
        currentState = WAIT_5S;
      }
      break;

    case WAIT_5S:
      // Ждём 5 секунд после выключения реле
      if (currentMillis - stateStartTime >= DELAY_5S) {
        // Возвращаемся в IDLE
        currentState = IDLE;
      }
      break;
  }

  // Сохраняем предыдущее состояние кнопки для детектирования фронта
  lastButtonState = buttonState;
}
